import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import "../styles/Profile.css";

const UserViewProfile = () => {
  const { id } = useParams();
  const [profileData, setProfileData] = useState(null);

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/users/${id}`);
        setProfileData(res.data);
      } catch (error) {
        console.error("Error fetching user profile:", error);
      }
    };

    fetchProfile();
  }, [id]);

  if (!profileData) return <p>Loading profile...</p>;

  const { user, profile } = profileData;

  return (
    <div className="profile-container">
      <h2 className="profile-title">User Profile</h2>
      <h3 className="username">{user.username}</h3>
      <p className="email">Email: {user.email}</p>
      <hr className="divider" />
      {profile ? (
        <>
          <p><strong>Bio:</strong> {profile.bio}</p>
          <p><strong>Instruments:</strong> {profile.instruments?.join(", ")}</p>
          <p><strong>Genres:</strong> {profile.genres?.join(", ")}</p>
          <p><strong>Years of Experience:</strong> {profile.yearsOfExperience}</p>
          <p><strong>City:</strong> {profile.city}</p>
          <p><strong>YouTube:</strong> {profile.youtube}</p>
          <p><strong>Instagram:</strong> {profile.instagram}</p>
        </>
      ) : (
        <p>No profile details available.</p>
      )}
    </div>
  );
};

export default UserViewProfile;
